INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12901, 'Job 41:1', 'Job', 41, 1, '&nbsp;سمندرى بلاګانې تۀ د کُنډې سره راويستلے شې، يا د دې ژبه د پړى سره تړلے شې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12902, 'Job 41:2', 'Job', 41, 2, '&nbsp;ولې تۀ دې ته پېزوان اچولے شې، يا يې په ژامنه کښې کُنډه اچولے شې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12903, 'Job 41:3', 'Job', 41, 3, '&nbsp;ولې دا به د رحم دپاره تا ته ډېر مِنتُونه وکړى؟ يا به نرمې خبرې درته وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12904, 'Job 41:4', 'Job', 41, 4, '&nbsp;دا به تا سره يو لوظ وکړى څۀ چې ټول عُمر به ستا غلام وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12905, 'Job 41:5', 'Job', 41, 5, '&nbsp;ولې تۀ به دا د يو مارغۀ په شان وساتې څۀ، يا تۀ به دا وتړې څۀ دپاره د دې چې ستا وينځې ورسره لوبې وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12906, 'Job 41:6', 'Job', 41, 6, '&nbsp;ولې سوداګر به د دې سودا وکړى؟ چې په بازار کښې يې خرڅ کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12907, 'Job 41:7', 'Job', 41, 7, '&nbsp;ولې د هغې په څرمن باندې غشى څۀ اثر کوى، او د دې سر د نېزو سره غوڅولے شې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12908, 'Job 41:8', 'Job', 41, 8, '&nbsp;کۀ تۀ خپل لاس د دې سره ولګوې، نو د جنګ په مزه به پوهه شې، او بيا به هيڅکله داسې نۀ کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12909, 'Job 41:9', 'Job', 41, 9, '&nbsp;نه، د دې نيول څۀ فائده نۀ کوى، او کوم ښکارى چې د دې د نيولو کوشش کوى نو هغه به راوغورزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12910, 'Job 41:10', 'Job', 41, 10, '&nbsp;هيڅ څوک هم دا جرأت نۀ شى کولے چې کار ورسره وساتى. او د دې په وړاندې څوک ټېنګېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12911, 'Job 41:11', 'Job', 41, 11, '&nbsp;چا ما له څۀ راکړى دى چې زۀ بدله ورکړم؟ د آسمان نه لاندې هر څۀ زما دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12912, 'Job 41:12', 'Job', 41, 12, '&nbsp;زۀ به د دې د بدن د اندامونو په حقله خاموشى نۀ اختياروم، يا د دې د لوئ طاقت او د دې د ښۀ بدن په حقله به وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12913, 'Job 41:13', 'Job', 41, 13, '&nbsp;د دې نه څرمن څوک ويستے شى؟ د دې ډکه څرمن څوک سورے کولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12914, 'Job 41:14', 'Job', 41, 14, '&nbsp;د دې د خولې ژامنې څوک کولاولے شى؟ ځکه چې د دې غاښونه خلق يروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12915, 'Job 41:15', 'Job', 41, 15, '&nbsp;د دې ملا د ډالونو قطارونو نه جوړه ده، دا د يو بل سره کلک انښلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12916, 'Job 41:16', 'Job', 41, 16, '&nbsp;د يو بل سره دومره نزدې دى، چې د دې په مينځ کښې هوا هم نۀ شى تېرېدلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12917, 'Job 41:17', 'Job', 41, 17, '&nbsp;دا د يو بل سره تړلى شوى دى، دې يو بل نيولے دے او د يو بل نه نۀ جدا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12918, 'Job 41:18', 'Job', 41, 18, '&nbsp;د دې انټوشى لکه د رڼا پړق وى، او د دې سترګې د سحر د سوروالى په شان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12919, 'Job 41:19', 'Job', 41, 19, '&nbsp;د دې خولې نه د ډيوو شُغلې ځى، او د اور ذرې ترې نه راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12920, 'Job 41:20', 'Job', 41, 20, '&nbsp;د دې د پوزې نه لوګے راوځى، لکه چې د پتيلې لاندې د بلو لوخو لوګے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12921, 'Job 41:21', 'Job', 41, 21, '&nbsp;د دې ساه سکارۀ بلوى، او د دې خولې نه يوه لمبه راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12922, 'Job 41:22', 'Job', 41, 22, '&nbsp;د دې څټ مضبوط دے، او چې چرته هم ځى نو هلته يره راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12923, 'Job 41:23', 'Job', 41, 23, '&nbsp;د دې د غوښې موړې د يوې بلې سره انښتې دى، دا مضبوطې جوړې دى او نۀ خوځيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12924, 'Job 41:24', 'Job', 41, 24, '&nbsp;د دې زړۀ د کاڼى په شان سخت دے، لکه د ژرندې د کاڼى په شان سخت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12925, 'Job 41:25', 'Job', 41, 25, '&nbsp;کله چې دا په خپله پاڅى نو طاقتور خلق ويريږى، او يرې نه وتښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12926, 'Job 41:26', 'Job', 41, 26, '&nbsp;داسې تُوره نشته چې زخمى يې کړى، نۀ پرې نېزه، نۀ غشے او نۀ ورباندې نرۍ نېزه څۀ اثر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12927, 'Job 41:27', 'Job', 41, 27, '&nbsp;دا اوسپنه د بوسو په شان ګڼى، او زېړ د ورَستو شوو لرګو په شان ګڼى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12928, 'Job 41:28', 'Job', 41, 28, '&nbsp;غشى دا نۀ شى شړلے، او د ليندې کاڼى خو ورته ګپ ښکارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12929, 'Job 41:29', 'Job', 41, 29, '&nbsp;لَوړ د بوسو په شان ګڼى، او د نرو نېزو په راويستلو پورې دا خندا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12930, 'Job 41:30', 'Job', 41, 30, '&nbsp;د دې خېټه د تېرو ماتو شوو شيشو په شان ده، دا په خټه باندې داسې نښه پرېږدى لکه چې په مېخونو سورے شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12931, 'Job 41:31', 'Job', 41, 31, '&nbsp;دا سمندر د يشېدلو اوبو په شان خوځوى، او دا سمندر داسې شاربى لکه شُملې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12932, 'Job 41:32', 'Job', 41, 32, '&nbsp;دا د خپل ځان شا ته يو پړقېدونکې کرښه پرېږدى، او سمندر تک سپين کړى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12933, 'Job 41:33', 'Job', 41, 33, '&nbsp;په زمکه باندې د دې ثانى نشته، دا يو داسې مخلوق دے چې نۀ يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12934, 'Job 41:34', 'Job', 41, 34, '&nbsp;دا په ټولو کښې ډېر مغرور دے، دا د ټولو ځناورو بادشاه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12935, 'Job 42:1', 'Job', 42, 1, '&nbsp;بيا ايُوب مالِک خُدائ له جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12936, 'Job 42:2', 'Job', 42, 2, '&nbsp;”ما ته پته ده چې تۀ هر څۀ کولے شې، او تا د خپل کار نه هيڅ څوک نۀ شى ايسارولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12937, 'Job 42:3', 'Job', 42, 3, '&nbsp;تا وفرمائيل چې، ”هغه څوک دے چې زما په حِکمت باندې د ناپوهۍ سره شک کوى؟“ هغه زۀ يم، ما د داسې څيزونو خبره کوله چې ما ته يې هيڅ پته نۀ وه، او هغه خبرې زما دپاره ډېرې عجيبه او لوئې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12938, 'Job 42:4', 'Job', 42, 4, '&nbsp;تا وفرمائيل چې، ”ما ته غوږ ونيسه او زۀ به وايم، زۀ به تپوس کوم او تۀ به ما له جواب راکوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12939, 'Job 42:5', 'Job', 42, 5, '&nbsp;ما مخکښې صرف ستا په حقله اورېدلى دى، خو اوس مې په خپلو سترګو وليدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12940, 'Job 42:6', 'Job', 42, 6, '&nbsp;نو ما چې څۀ وئيلى دى نو په هغې شرمنده يم، او په خاورو او ايرو کښې توبه وباسم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12941, 'Job 42:7', 'Job', 42, 7, '&nbsp;کله چې مالِک خُدائ د ايُوب سره دا خبرې وکړې، نو مالِک خُدائ تيمانى اليفز ته وفرمائيل، ”زۀ تا او ستا دوو ملګرو ته سخت غصه يم، ځکه چې تاسو زما هغه خبره نۀ ده کړې چې کومه صحيح ده، لکه څنګه چې زما خِدمت کوونکى ايُوب کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12942, 'Job 42:8', 'Job', 42, 8, '&nbsp;نو په دې وجه اوس اووۀ غوَيى او اووۀ ګډان بوځه او زما خِدمت کوونکى ايُوب له ورشه او د خپل ځان دپاره دا د سوزېدونکې نذرانې په توګه پېش کړه، نو زما خِدمت کوونکے ايُوب به ستا دپاره دُعا وکړى، ځکه چې زۀ به د هغۀ دُعا قبلوم او ستاسو د کم عقلتوب په مطابق کار به درسره نۀ کوم، ځکه چې تاسو زما هغه خبره نۀ ده کړې چې کومه صحيح ده، لکه څنګه چې زما خِدمت کوونکى ايُوب کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12943, 'Job 42:9', 'Job', 42, 9, '&nbsp;نو تيمانى اليفز، شوحى بِلداد او نعماتى ضوفر لاړل او چې مالِک خُدائ څنګه فرمائيلى وُو هم هغه شان يې وکړل، او مالِک خُدائ د ايُوب دُعا قبوله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12944, 'Job 42:10', 'Job', 42, 10, '&nbsp;نو کله چې ايُوب د خپلو ملګرو دپاره دُعا وکړه نو خُدائ پاک هغۀ له بيا برکت ورکړو، او چې ايُوب مخکښې څۀ لرل نو مالِک خُدائ هغۀ له د هغې يو په دوه نور هم زيات ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12945, 'Job 42:11', 'Job', 42, 11, '&nbsp;نو هلته هغۀ له د هغۀ ټول وروڼه خوېندې او ټول پخوانى خپل پردى راغلل او هغوئ د هغۀ په کور کښې روټۍ وخوړه. او هغوئ ورته مينه ښکاره کړه او د هغه تکليفونو په وجه يې هغۀ له تسلى ورکړه چې مالِک خُدائ په هغۀ راوستى وُو. او هغوئ هر يو هغۀ له لږې پېسې او يوه د سرو زرو ګوتمه ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12946, 'Job 42:12', 'Job', 42, 12, '&nbsp;نو مالِک خُدائ د ايُوب وروستنے عُمر د اول عُمر نه زيات برکتناک کړو، او د هغۀ څوارلس زره ګډې، شپږ زره اوښان، دوه زره غوَيى او يو زر خرۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12947, 'Job 42:13', 'Job', 42, 13, '&nbsp;د هغۀ اووۀ زامن او درې لوڼه هم وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12948, 'Job 42:14', 'Job', 42, 14, '&nbsp;هغۀ په وړومبۍ لور باندې يميمه، په دوېمه قصياه او په درېمه باندې قرن‌هپوک نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12949, 'Job 42:15', 'Job', 42, 15, '&nbsp;او په هغه ټول مُلک کښې د ايُوب د لوڼو په شان ښائسته ښځې نۀ وې، خپل پلار هغوئ له د دوئ د وروڼو په شان ميراث ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12950, 'Job 42:16', 'Job', 42, 16, '&nbsp;ايُوب د دې نه پس يو سل او څلوېښت کاله ژوندے وو او د څلورم نسل پورې خپل بچى او نمسى يې وليدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12951, 'Job 42:17', 'Job', 42, 17, '&nbsp;نو بيا ايُوب په پوخ عُمر کښې مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12952, 'Psalms 1:1', 'Psalms', 1, 1, '&nbsp;نو هغه بختور دے او بختور به وى څوک چې د بدعملو په خبرو عمل نۀ کوى، په لار د ګناهګارو چې تلل نۀ کوى، د مسخره کوونکو په ډله کښې چې نۀ کښېنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12953, 'Psalms 1:2', 'Psalms', 1, 2, '&nbsp;خو په قانون د مالِک خُدائ چې خوشحاليږى، شپه او ورځ چې د هغۀ په شريعت غور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12954, 'Psalms 1:3', 'Psalms', 1, 3, '&nbsp;نو هغه به د داسې ونې په مثال وى، کومه ونه چې د ولې په غاړه نال وى، مېوه کوى په موسم کښې مېوه داره وى پاڼې يې تل شنې وى او په ‎ژوندون کښې کاميابه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12955, 'Psalms 1:4', 'Psalms', 1, 4, '&nbsp;خو بدعمله داسې نۀ دى، دوئ لکه د بوسو په شان وى، د هوا سره الوځى په ځائ به پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12956, 'Psalms 1:5', 'Psalms', 1, 5, '&nbsp;نو ځکه په وخت د عدالت به بدعمله مجرم شى، ګناهګاران به د صادقانو سره شمېرلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12957, 'Psalms 1:6', 'Psalms', 1, 6, '&nbsp;بې‌شکه مالِک خُدائ د صادقانو د لارې خيال ساتى، په لار د تباهۍ خو بدعمله ورروان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12958, 'Psalms 2:1', 'Psalms', 2, 1, '&nbsp;قومونه ولې په قهر شول او اُمتونه ولې بې‌فائدې سازشونه کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12959, 'Psalms 2:2', 'Psalms', 2, 2, '&nbsp;د دُنيا بادشاهان راپورته شول او حاکمان د مالِک خُدائ خلاف او د هغۀ د مسيح په خلاف يو ځائ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12960, 'Psalms 2:3', 'Psalms', 2, 3, '&nbsp;”راځئ زنځيرونه به مات کړُو، د خُدائ د غلامۍ رسۍ به وغورزوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12961, 'Psalms 2:4', 'Psalms', 2, 4, '&nbsp;مالِک خُدائ په هغوئ پورې خاندى، کوم چې آسمان کښې ناست دے هغه ورپورې ټوقې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12962, 'Psalms 2:5', 'Psalms', 2, 5, '&nbsp;نو بيا يې هغه په خپله غصه کښې رټى او په خپل قهر او غضب سره يې يروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12963, 'Psalms 2:6', 'Psalms', 2, 6, '&nbsp;مالِک خُدائ فرمائى، ”ما مقرر کړے دے په خپل مقدس غر، ما دے په صيون کښې خپل بادشاه کړو مقرر.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12964, 'Psalms 2:7', 'Psalms', 2, 7, '&nbsp;زۀ بادشاه به د مالِک خُدائ د حُکم اِعلان وکړم، ”تۀ زما زوئ يې او د نن نه زۀ ستا پلار شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12965, 'Psalms 2:8', 'Psalms', 2, 8, '&nbsp;زما نه وکړه سوال، زۀ به درکړم ټول قومونه، زۀ ميراث کښې تا له در به کړم د دُنيا ټول جائيدادونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12966, 'Psalms 2:9', 'Psalms', 2, 9, '&nbsp;د خاورين لوښى په شان به يې تۀ ډکرې کړې، هغوئ به تۀ په سيخ د اوسپنې ټوټې کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12967, 'Psalms 2:10', 'Psalms', 2, 10, '&nbsp;اے حکمرانانو هوښيار شئ، اے د دُنيا بادشاهانو خبردار شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12968, 'Psalms 2:11', 'Psalms', 2, 11, '&nbsp;د يرې سره د مالِک خُدائ خِدمت کوئ، او په رپېدو سره د هغۀ خوشحالى کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12969, 'Psalms 2:12', 'Psalms', 2, 12, '&nbsp;د هغۀ د زوئ په وړاندې کۀ د زړۀ د اخلاصه ټيټ نۀ شئ، نو هغه زر غصه کيږى، او ناڅاپه به تباه شئ، هغه به بختور شى څوک چې د هغۀ پناه کښې راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12970, 'Psalms 3:1', 'Psalms', 3, 1, '&nbsp;اے مالِکه خُدايه څومره ډېر دى دشمنان زما، څومره ډېر را‎پاڅېدلى دى خلاف زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12971, 'Psalms 3:2', 'Psalms', 3, 2, '&nbsp;ډېر زما په حقله داسې وائى، ”هغه به خُدائ پاک نۀ بچ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12972, 'Psalms 3:3', 'Psalms', 3, 3, '&nbsp;تۀ خو زما ډال يې چې زما نه ګېرچاپېره يې، تۀ زما جلال يې، څوک چې زما سترګې اوچتوى، اے مالِکه خُدايه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12973, 'Psalms 3:4', 'Psalms', 3, 4, '&nbsp;کله چې مالِک خُدائ ته په اوچت آواز ژړا کوم، خپل مقدس غر نه هغه ما ته جواب راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12974, 'Psalms 3:5', 'Psalms', 3, 5, '&nbsp;چې څملمه اودۀ شمه په حفاظت کښې پاڅم، ځکه چې زۀ د مالِک خُدائ د نظر لاندې يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12975, 'Psalms 3:6', 'Psalms', 3, 6, '&nbsp;يره ترې نه نۀ کوم هغوئ کۀ هر څومره ډېر وى کۀ زۀ په کښې د هرې خوا نه ګېر يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12976, 'Psalms 3:7', 'Psalms', 3, 7, '&nbsp;مالِکه خُدايه پاڅه، خُدايه ما ترې خلاص کړه، د دشمن مې ژامنې ماتې کړه، غاښونه د بدعملو مات کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12977, 'Psalms 3:8', 'Psalms', 3, 8, '&nbsp;خلاصون د مالِک خُدائ نه راځى. ستا په خلقو ستا برکت دې همېشه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12978, 'Psalms 4:1', 'Psalms', 4, 1, '&nbsp;نو اوره زما سوال کله چې تا ته په ژړا يم، تۀ چې وائې زما په حقله خُدايه، زۀ چې بې‌ګناه يم. زما مشکل آسان کړه، مهربان شه سوال مې اوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12979, 'Psalms 4:2', 'Psalms', 4, 2, '&nbsp;اے خلقو، ترڅو به تاسو زما پاکه جامه ښيرنه کړئ؟ ترڅو پورې به تاسو فضولياتو سره مينه کړئ؟ ترڅو پورې به تاسو په دروغو پسې ګرځئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12980, 'Psalms 4:3', 'Psalms', 4, 3, '&nbsp;په دې باندې خبر شئ چې خپل خلق يې د خپل ځان دپاره د نورو خلقو نه جدا کړى دى، زما سوالونه قبلوى کله چې مالِک خُدائ ته ما کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12981, 'Psalms 4:4', 'Psalms', 4, 4, '&nbsp;د غصې په وجه ګناه مۀ کوئ، چې خپلو کټونو له لاړ شئ فکر وکړئ او خاموش شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12982, 'Psalms 4:5', 'Psalms', 4, 5, '&nbsp;خپلې د صداقت قربانۍ وړاندې کړئ او تل توکل په مالِک خُدائ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12983, 'Psalms 4:6', 'Psalms', 4, 6, '&nbsp;ډېر خلق تپوس کوى، ”مونږ سره به څوک ښۀ وى؟ اے مالِکه خُدايه، خپله د مخ رڼا دې په مونږ وځلوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12984, 'Psalms 4:7', 'Psalms', 4, 7, '&nbsp;تۀ به زما زړۀ د يو لوئې خوشحالۍ نه ډک کړې د هغوئ نه هم ډېر زيات څوک چې ډېر غنم او شراب لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12985, 'Psalms 4:8', 'Psalms', 4, 8, '&nbsp;زۀ به په بې‌غمۍ سره اودۀ شم، يواځې تۀ اے مالِکه خُدايه، زما ژوند په حفاظت تېر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12986, 'Psalms 5:1', 'Psalms', 5, 1, '&nbsp;اے مالِکه خُدايه زما خبرو ته غوږ شه، زما اسويلو ته توجو وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12987, 'Psalms 5:2', 'Psalms', 5, 2, '&nbsp;زما د ژړا آواز د مدد دپاره واوره، زۀ تا ته سوال کومه زما خُدايه، زما بادشاه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12988, 'Psalms 5:3', 'Psalms', 5, 3, '&nbsp;زما واوره سحر کښې زۀ تا ته آواز کوم، هر سحر کښې زۀ تا ته درخواست کوم مالِکه خُدايه ستا په طمع اِنتظار کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12989, 'Psalms 5:4', 'Psalms', 5, 4, '&nbsp;يو تۀ هغه خُدائ يې چې په بدو نۀ خوشحاليږى، بد کرداره به تا سره نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12990, 'Psalms 5:5', 'Psalms', 5, 5, '&nbsp;ستا په وړاندې مغرور خو ودرېدے نۀ شى، کوې کرکه د هغوئ نه چې بدکاره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12991, 'Psalms 5:6', 'Psalms', 5, 6, '&nbsp;تۀ هغه تباه کوې، څوک چې دروغژن وى، مالِک خُدائ دوکه بازو او خونکارو نه کرکه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12992, 'Psalms 5:7', 'Psalms', 5, 7, '&nbsp;ستا د لوئ رحم په وجه به زۀ دننه شم ستا کور ته، ډېر په يره په سجده به شم ستا مقدس کور ته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12993, 'Psalms 5:8', 'Psalms', 5, 8, '&nbsp;اے مالِکه خُدايه، په سبب زما د دشمنانو، په خپل صداقت سره دې زما رهنمائى وکړه، خپله نېغه لار دې ما ته راوښايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12994, 'Psalms 5:9', 'Psalms', 5, 9, '&nbsp;په خولۀ يې اعتبار نۀ وى زړونه يې د تباهۍ نه ډک دى. او په ژبه دروغ وائى او مرۍ يې کولاو قبر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12995, 'Psalms 5:10', 'Psalms', 5, 10, '&nbsp;اے پاکه خُدايه هغوئ ګناهګار حساب کړه، هغوئ په خپلو دامونو کښې راګېر کړه. د ډېرو ګناهونو په وجه دوئ د خپل ځان نه وشړه، ځکه چې هغوئ ستا خلاف سرکشى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12996, 'Psalms 5:11', 'Psalms', 5, 11, '&nbsp;خو څوک چې ستا پناه واخلى هغوئ دې خوشحالى کوى، وائى سندرې تل تر تله بې‌غمۍ سره وى دې ستا امان کښې ستا امان دې وى هغوئ باندې هغوئ دې خوشحال وى چې ستا نوم سره مينه ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12997, 'Psalms 5:12', 'Psalms', 5, 12, '&nbsp;اے مالِکه خُدايه، تۀ په خپله نېکانو ته برکت ورکوې، تۀ د خپل رحم ډال هغوئ نه چاپېره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12998, 'Psalms 6:1', 'Psalms', 6, 1, '&nbsp;اے مالِکه خُدايه ما مۀ رټه په خپله غصه کښې ما ته قهر مۀ کوه زما په سمولو کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12999, 'Psalms 6:2', 'Psalms', 6, 2, '&nbsp;رحم په ما وکړه زۀ کمزورے يم مالِکه خُدايه، شفا راکړه هډُوکى مې ماتيږى مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13000, 'Psalms 6:3', 'Psalms', 6, 3, '&nbsp;په زړۀ يمه بيمار دا به تر کومې وى اے مالِکه خُدايه دا به تر کومې وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');